(()=>{document.addEventListener("DOMContentLoaded",()=>{let r=document.querySelector("[data-ws-review-summary]");if(!r||typeof WooShopReviews=="undefined")return;let e=r.querySelector("[data-ws-reviews-list]"),t=e==null?void 0:e.dataset.productId;if(!e||!t)return;let d=async(a=0,s=1)=>{e.classList.add("is-loading");let o=new FormData;o.append("action",WooShopReviews.action),o.append("nonce",WooShopReviews.nonce),o.append("product_id",t),o.append("rating",a),o.append("page",s);try{let i=await(await fetch(WooShopReviews.ajaxUrl,{method:"POST",body:o})).json();if(!i.success)throw new Error(WooShopReviews.error);e.innerHTML=i.data.html}catch(n){e.innerHTML=`
				<div class="alert alert-danger">
					${WooShopReviews.error}
				</div>
			`,console.error("WooShop reviews error:",n)}finally{e.classList.remove("is-loading")}};r.querySelectorAll("[data-ws-review-rating]").forEach(a=>{a.addEventListener("click",()=>{let s=parseInt(a.dataset.wsReviewRating,10);r.querySelectorAll("[data-ws-review-rating]").forEach(o=>{o.classList.remove("is-active")}),a.classList.add("is-active"),d(s,1)})})});})();
